.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 46px;
  padding: 12px 18px;
  border-radius: 9px;
  border: 1px solid transparent;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  transition:
    background 0.15s,
    color 0.15s;
}
.ds-button-primary {
  background: var(--green);
  color: #fff;
}
.ds-button-primary:hover:not(:disabled) {
  background: #174732;
}button:focus-visible,a:focus-visible,input:focus-visible,[role="combobox"]:focus-visible {outline:3px solid #497945;outline-offset:4px;} button:disabled{cursor:not-allowed;opacity:.48;}

