.ds-search-input {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 0 14px;
  min-height: 46px;
  flex: 1;
  max-width: 460px;
  min-width: 0;
  color: var(--muted);
}
.ds-search-input input {
  border: 0;
  outline: none;
  background: none;
  width: 100%;
  min-width: 0;
  font-size: 14px;
  color: var(--ink);
  padding: 13px 0;
}
.ds-search-input:focus-within {
  outline: 2px solid var(--green);
  outline-offset: 2px;
}button:focus-visible,a:focus-visible,input:focus-visible,[role="combobox"]:focus-visible {outline:3px solid #497945;outline-offset:4px;} button:disabled{cursor:not-allowed;opacity:.48;}

.ds-main-nav a {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  min-height: 50px;
  border-radius: 10px;
  color: #c3d0c8;
  font-size: 15px;
  font-weight: 500;
}
.ds-main-nav a:hover {
  background: #263b31;
  color: #fff;
}
.ds-main-nav a.ds-active {
  background: var(--accent);
  color: #203a27;
  font-weight: 700;
}button:focus-visible,a:focus-visible,input:focus-visible,[role="combobox"]:focus-visible {outline:3px solid #497945;outline-offset:4px;} button:disabled{cursor:not-allowed;opacity:.48;}

.ds-status-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #756337;
  background: #faf3e3;
  padding: 6px 9px;
  border-radius: 5px;
}
.ds-status-chip.ds-completed {
  color: var(--green);
  background: #edf4e7;
}
.ds-status-chip i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
}button:focus-visible,a:focus-visible,input:focus-visible,[role="combobox"]:focus-visible {outline:3px solid #497945;outline-offset:4px;} button:disabled{cursor:not-allowed;opacity:.48;}

.ds-upload-panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  min-width: 0;
}
.ds-viewer,
.ds-upload-panel,
.ds-results-panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  min-width: 0;
}
.ds-upload-panel {
  padding: 26px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
  min-height: 620px;
}
.ds-panel-heading h3 {
  font-size: 18px;
  letter-spacing: -0.35px;
}button:focus-visible,a:focus-visible,input:focus-visible,[role="combobox"]:focus-visible {outline:3px solid #497945;outline-offset:4px;} button:disabled{cursor:not-allowed;opacity:.48;}

.ds-model-select-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  text-align: left;
  border: 1px solid #bfcec3;
  border-radius: 9px;
  background: #fff;
  padding: 13px 15px;
  gap: 14px;
  min-height: 72px;
}
.ds-model-select-trigger:hover:not(:disabled) {
  border-color: var(--green);
}
.ds-model-select-trigger[aria-expanded="true"] {
  border-color: var(--green);
  box-shadow: 0 0 0 2px #245c4614;
}
.ds-model-select-trigger strong {
  font-size: 15px;
  font-weight: 700;
  display: block;
}
.ds-model-select-trigger small {
  display: block;
